#effect Duotono
#desc Sombras y luces con dos colores
#input A Imagen

#color sombra #1a0b3d
#color luz #ffb36b
#param contraste 1.2 0 3

float l = luma(@A.rgb);
l = clamp((l - 0.5) * @contraste + 0.5, 0.0, 1.0);
@out.rgb = mix(@sombra, @luz, l);

#effect Grano y viñeta
#desc Grano animado de película con viñeta
#input A Imagen

#param grano 0.08 0 0.5
#param vig 1.2 0 3

vec2 d = @uv - 0.5;
d.x *= @res.x / @res.y;
float n = hash13(vec3(@P, floor(@time * 24.0))) - 0.5;
@out.rgb += n * @grano;
@out.rgb *= 1.0 - @vig * dot(d, d);

#effect Pixelado
#desc Bloques cuadrados de tamaño ajustable
#input A Imagen

#param bloque 12 2 64

vec2 cell = vec2(@bloque) / @res;
vec2 uv = (floor(@uv / cell) + 0.5) * cell;
@out = A(uv);

#effect Semitono
#desc Puntos de imprenta según la luminancia
#input A Imagen

#param celda 10 4 40
#param angulo 45 0 90
#color tinta #111111
#color papel #f4efe4

float a = radians(@angulo);
mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
vec2 p = R * @P;
vec2 id = floor(p / @celda);
vec2 f = fract(p / @celda) - 0.5;
vec2 centro = transpose(R) * ((id + 0.5) * @celda);
float l = luma(A(centro / @res).rgb);
float r = sqrt(1.0 - l) * 0.75;
float punto = 1.0 - smoothstep(r - 0.06, r + 0.06, length(f));
@out = vec4(mix(@papel, @tinta, punto), 1.0);

#effect Pantalla CRT
#desc Curvatura de barril y líneas de barrido
#input A Imagen

#param curva 0.12 0 0.4
#param lineas 0.35 0 1

vec2 c = @uv * 2.0 - 1.0;
c *= 1.0 + @curva * dot(c, c) * 0.5;
vec2 uv = c * 0.5 + 0.5;
if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
  @out = vec4(0.0, 0.0, 0.0, 1.0);
} else {
  vec4 col = A(uv);
  float s = 0.5 + 0.5 * sin(uv.y * @res.y * 3.14159);
  col.rgb *= 1.0 - @lineas * (1.0 - s);
  @out = col;
}

#effect Ondas
#desc Deformación ondulante animada
#input A Imagen

#param amp 0.01 0 0.05
#param freq 18 1 80
#param vel 2 0 10

vec2 uv = @uv;
uv.x += sin(uv.y * @freq + @time * @vel) * @amp;
uv.y += cos(uv.x * @freq * 0.7 + @time * @vel) * @amp;
@out = A(uv);

#effect Caleidoscopio
#desc Simetría radial de N segmentos
#input A Imagen

#param segmentos 6 2 16
#param giro 0 0 6.2832

vec2 p = @uv - 0.5;
p.x *= @res.x / @res.y;
float r = length(p);
float a = atan(p.y, p.x) + @giro;
float seg = 6.28318 / floor(@segmentos);
a = abs(mod(a, seg) - seg * 0.5);
p = vec2(cos(a), sin(a)) * r;
p.x /= @res.x / @res.y;
@out = A(p + 0.5);

#effect Bordes neón
#desc Contornos Sobel brillantes sobre la imagen oscurecida
#input A Imagen

#color neon #00f0ff
#param fuerza 3 0 10
#param fondo 0.25 0 1

// Luminancia de A desplazada (dx, dy) píxeles
float L(float dx, float dy) {
  return luma(A(@uv + vec2(dx, dy) / @res).rgb);
}

float gx = L(1.0, 1.0) + 2.0 * L(1.0, 0.0) + L(1.0, -1.0)
         - L(-1.0, 1.0) - 2.0 * L(-1.0, 0.0) - L(-1.0, -1.0);
float gy = L(-1.0, 1.0) + 2.0 * L(0.0, 1.0) + L(1.0, 1.0)
         - L(-1.0, -1.0) - 2.0 * L(0.0, -1.0) - L(1.0, -1.0);
float e = clamp(length(vec2(gx, gy)) * @fuerza, 0.0, 1.0);
@out.rgb = @A.rgb * @fondo + @neon * e;

#effect Desenfoque radial
#desc Zoom borroso hacia un centro ajustable
#input A Imagen

#param fuerza 0.15 0 0.5
#param cx 0.5 0 1
#param cy 0.5 0 1

vec2 c = vec2(@cx, @cy);
vec4 acc = vec4(0.0);
for (int i = 0; i < 24; i++) {
  float k = float(i) / 23.0;
  acc += A(mix(@uv, c, k * @fuerza));
}
@out = acc / 24.0;

#effect Mezcla con máscara
#desc Funde A y B según un atributo de C
#input A Imagen 1
#input B Imagen 2
#input C Máscara scalar

#param suavidad 0.1 0 0.5
#param umbral 0.5 0 1

// @Cv = canal elegido de C (luminancia por defecto); sin conectar vale 1
float m = smoothstep(@umbral - @suavidad, @umbral + @suavidad, @Cv);
@out = mix(@A, @B, m);

#effect Plasma
#desc Generador animado de color, sin entradas

#param escala 3 0.5 12
#param vel 0.6 0 3

vec2 p = (@uv - 0.5) * vec2(@res.x / @res.y, 1.0) * @escala;
float t = @time * @vel;
float v = sin(p.x + t) + sin(p.y * 1.3 - t) + sin(length(p) * 1.7 + t * 1.4);
v += fbm(vec3(p * 0.6, t * 0.3), 4) * 2.0;
vec3 col = hsv2rgb(vec3(fract(v * 0.15 + t * 0.05), 0.75, 0.95));
@out = vec4(col, 1.0);

#effect Pulso
#desc Zoom y brillo que laten con los graves del audio
#input A Imagen
#input B Audio

#param zoom 0.08 0 0.3
#param brillo 0.6 0 2
#color destello #ffd9a0

// Conecta un nodo Audio (capa «Valores») a la entrada B:
// @B.r = volumen, @B.g = graves, @B.b = agudos
float graves = @B.g;
vec2 c = @uv - 0.5;
vec4 col = A(0.5 + c / (1.0 + @zoom * graves));
col.rgb += @destello * @brillo * graves * graves;
@out = vec4(col.rgb, col.a);

#effect Anaglifo 3D
#desc Fusiona el ojo izquierdo (rojo) y el derecho (cian) como el cine 3D clásico
#input A Ojo izquierdo
#input B Ojo derecho
#input C Profundidad scalar

#enum modo Color | Grises | Optimizado (Dubois)
#param separacion 6 -40 40
#color izquierda #ff0000
#color derecha #00ffff

// A = ojo izquierdo, B = ojo derecho. Si B no está conectada, el par se
// inventa desplazando A. Con un mapa en C (claro = cerca), el desplazamiento
// cambia por píxel y la imagen gana relieve.
float k = uHasC > 0.5 ? (@Cv - 0.5) * 2.0 : 1.0;
vec2 off = vec2(@separacion * k * 0.5 / @res.x, 0.0);
vec4 L = A(@uv + off);
vec4 R = uHasB > 0.5 ? B(@uv - off) : A(@uv - off);

vec3 col;
if (@modo == 1) {
  // Grises: menos rivalidad de color, más cómodo de ver
  col = luma(L.rgb) * @izquierda + luma(R.rgb) * @derecha;
} else if (@modo == 2) {
  // Matrices de Dubois para rojo/cian: menos "fantasmas"
  col = vec3(
    dot(L.rgb, vec3( 0.456,  0.500,  0.176)) + dot(R.rgb, vec3(-0.043, -0.088, -0.002)),
    dot(L.rgb, vec3(-0.040, -0.038, -0.016)) + dot(R.rgb, vec3( 0.378,  0.734, -0.018)),
    dot(L.rgb, vec3(-0.015, -0.021, -0.005)) + dot(R.rgb, vec3(-0.072, -0.113,  1.226)));
} else {
  // Color: cada ojo pasa por su filtro
  col = L.rgb * @izquierda + R.rgb * @derecha;
}
@out = vec4(clamp(col, 0.0, 1.0), max(L.a, R.a));

#effect VHS
#desc Líneas de barrido, color corrido, tracking y ruido de cinta VHS
#input A Imagen

#param lineas 0.35 0 1
#param grosor 2 1 6
#param sangrado 8 0 24
#param desfase 3 -12 12
#param temblor 1.5 0 8
#param tracking 0.6 0 1
#param cabeza 1 0 1
#param ruido 0.08 0 0.4
#param saturacion 0.85 0 1.5

// YIQ: el espacio de color de la TV analógica (Y = brillo, I/Q = color)
vec3 rgb2yiq(vec3 c) {
  return mat3(0.299, 0.596, 0.211,
              0.587, -0.274, -0.523,
              0.114, -0.322, 0.312) * c;
}
vec3 yiq2rgb(vec3 c) {
  return mat3(1.0, 1.0, 1.0,
              0.956, -0.272, -1.106,
              0.621, -0.647, 1.703) * c;
}

float px = 1.0 / @res.x;
float linea = floor(@P.y / @grosor);
float cuadro = floor(@time * 30.0);

// Temblor por línea + ondulación lenta de la cinta (en píxeles)
float dx = (hash13(vec3(linea, cuadro, 3.1)) - 0.5) * @temblor;
dx += sin(@uv.y * 40.0 + @time * 3.0) * @temblor * 0.4;

// Banda de tracking que sube rodando
float pos = fract(@time * 0.12);
float banda = (1.0 - smoothstep(0.0, 0.035, abs(@uv.y - pos))) * @tracking;
dx += banda * (hash13(vec3(linea, cuadro, 7.7)) - 0.3) * 40.0;

// Ruido de cambio de cabeza en el borde inferior
float cab = smoothstep(0.035, 0.0, @uv.y) * @cabeza;
dx += cab * 25.0 * (1.0 + hash13(vec3(linea, cuadro, 9.0)));

vec2 uv = @uv + vec2(dx * px, 0.0);

// Brillo nítido; color desenfocado y corrido en horizontal
float Y = rgb2yiq(A(uv).rgb).x;
vec2 IQ = vec2(0.0);
for (int i = 0; i < 8; i++) {
  float o = (float(i) / 7.0 - 0.5) * @sangrado + @desfase;
  IQ += rgb2yiq(A(uv + vec2(o * px, 0.0)).rgb).yz;
}
IQ = IQ / 8.0 * @saturacion;
vec3 col = yiq2rgb(vec3(Y, IQ));

// Líneas de barrido
float sl = 0.5 + 0.5 * cos(@P.y / @grosor * 6.28318);
col *= 1.0 - @lineas * (1.0 - sl);

// Ruido de señal, nieve en la banda de tracking y en la franja inferior
col += (hash13(vec3(@P, cuadro)) - 0.5) * @ruido;
col += banda * hash13(vec3(floor(@P.x * 0.5), linea, cuadro)) * 0.35;
col += cab * hash13(vec3(@P, cuadro + 1.0)) * 0.3;

@out = vec4(clamp(col, 0.0, 1.0), 1.0);

#effect Blanco y negro intenso
#desc Alto contraste con filtro de color, curva en S, claridad y grano
#input A Imagen

#enum filtro Neutro | Rojo | Naranja | Amarillo | Verde | Azul
#enum estilo Fotográfico | Gráfico (umbral)
#param contraste 1.8 0.3 4
#param negros 0.06 0 0.5
#param blancos 0.94 0.5 1
#param claridad 0.6 0 2
#param radio 6 1 24
#param umbral 0.5 0 1
#param suavidad 0.04 0 0.3
#param grano 0.05 0 0.3

// Mezcla de canales como un filtro frente al lente
// (Rojo oscurece cielos y azules; Verde aclara follaje; Azul aclara cielos)
float gris(vec3 c) {
  vec3 W[6] = vec3[6](
    vec3(0.2126, 0.7152, 0.0722),   // Neutro
    vec3(0.90, 0.10, 0.00),         // Rojo
    vec3(0.70, 0.30, 0.00),         // Naranja
    vec3(0.50, 0.45, 0.05),         // Amarillo
    vec3(0.20, 0.70, 0.10),         // Verde
    vec3(0.10, 0.20, 0.70));        // Azul
  return dot(c, W[@filtro]);
}

// Curva en S normalizada: 0 → 0, 1 → 1, más dura con k mayor
float curvaS(float x, float k) {
  float a = 1.0 / (1.0 + exp(k * 0.5));
  float b = 1.0 / (1.0 + exp(-k * 0.5));
  return (1.0 / (1.0 + exp(-k * (x - 0.5))) - a) / (b - a);
}

float g = gris(@A.rgb);

// Claridad: compara con el promedio de un anillo de 12 muestras
vec2 px = @radio / @res;
float prom = 0.0;
for (int i = 0; i < 12; i++) {
  float ang = float(i) * 0.5236;
  float r = (i % 2 == 0) ? 1.0 : 0.5;
  prom += gris(A(@uv + vec2(cos(ang), sin(ang)) * px * r).rgb);
}
prom /= 12.0;
g += @claridad * (g - prom);

// Puntos de negro y blanco, luego la curva
g = clamp((g - @negros) / max(@blancos - @negros, 0.001), 0.0, 1.0);
if (@estilo == 1) {
  g = smoothstep(@umbral - @suavidad, @umbral + @suavidad, g);
} else {
  g = curvaS(g, 4.0 * @contraste);
}

// Grano de película, más visible en los medios tonos
float n = hash13(vec3(@P, floor(@time * 24.0))) - 0.5;
g += n * @grano * (0.3 + 2.8 * g * (1.0 - g));

@out = vec4(vec3(clamp(g, 0.0, 1.0)), @A.a);

#effect Lluvia digital
#desc Cascada de glifos estilo Matrix que dibuja la imagen de entrada
#input A Imagen

#param tamano 14 6 48
#param velocidad 1 0 4
#param estela 0.35 0.05 1
#param gotas 2 1 3
#param fondo 0.3 0 1
#param cambio 3 0 12
#param contraste 1.3 0.3 4
#param brillo 1.3 0 3
#enum color Verde clásico | Colores de la imagen
#color tinta #3dff6e
#color cabeza #e2ffe9

// Glifo procedural: cuadrícula de 3×5 trazos dentro de la celda.
// f = posición dentro de la celda (0–1), id = qué glifo
float glifo(vec2 f, float id) {
  vec2 g = (f - vec2(0.14, 0.08)) / vec2(0.72, 0.84);
  if (g.x < 0.0 || g.x > 1.0 || g.y < 0.0 || g.y > 1.0) return 0.0;
  vec2 q = floor(g * vec2(3.0, 5.0));
  if (hash13(vec3(id, 5.0, 1.0)) > 0.5) q.x = min(q.x, 2.0 - q.x);  // la mitad, simétricos
  float on = step(0.45, hash13(vec3(q, id)));
  vec2 c = fract(g * vec2(3.0, 5.0)) - 0.5;
  return on * (1.0 - smoothstep(0.38, 0.5, max(abs(c.x), abs(c.y))));
}

vec2 cell = vec2(@tamano * 0.7, @tamano);   // celdas más altas que anchas
vec2 id = floor(@P / cell);
vec2 f = fract(@P / cell);
vec2 cuv = (id + 0.5) * cell / @res;        // centro de la celda (0–1)
float filas = @res.y / cell.y;

// Gotas de esta columna: cabeza que baja celda por celda y estela encima
float tr = 0.0, cab = 0.0;
float vcol = 0.5 + hash13(vec3(id.x, 1.0, 2.0));
for (int k = 0; k < 3; k++) {
  if (float(k) >= @gotas) break;
  float off = hash13(vec3(id.x, float(k), 3.0));
  float y = (1.0 + @estela) - fract(off + @time * @velocidad * vcol * 0.15) * (1.0 + 2.0 * @estela);
  y = floor(y * filas) / filas;
  float d = cuv.y - y;                       // distancia por encima de la cabeza
  if (d >= 0.0 && d < @estela) tr = max(tr, 1.0 - d / @estela);
  cab = max(cab, 1.0 - step(0.5 / filas, abs(d)));
}

// Glifo que cambia con el tiempo, cada celda a su ritmo
float ritmo = @cambio * (0.4 + hash13(vec3(id, 9.0)));
float gid = hash13(vec3(id, floor(@time * ritmo + hash13(vec3(id, 4.0))))) * 1000.0;
float g = glifo(f, gid);

// La imagen decide cuánto brilla cada glifo
vec3 src = A(cuv).rgb;
float lum = uHasA > 0.5 ? pow(clamp(luma(src), 0.0, 1.0), @contraste) : 1.0;
vec3 tinte = (@color == 1 && uHasA > 0.5) ? src / max(max(src.r, max(src.g, src.b)), 0.001) : @tinta;
// Sin imagen: lluvia clásica (solo las estelas)
float inten = uHasA > 0.5 ? lum * (@fondo + (1.0 - @fondo) * tr) : tr;

vec3 col = g * (tinte * inten * @brillo + @cabeza * cab * (0.15 + 0.85 * lum));
@out = vec4(clamp(col, 0.0, 1.0), 1.0);

#effect Transición: barrido diagonal
#desc Para Secuencia: barrido en diagonal con borde brillante
#input A Saliente
#input B Entrante

// Secuencia controla @progreso (0 → solo A, 1 → solo B)
#param progreso 0.5 0 1
#param suavidad 0.08 0.01 0.5
#color borde #ffffff

float d = (@uv.x + @uv.y) * 0.5;
float e = @progreso * (1.0 + 2.0 * @suavidad) - @suavidad;
float m = smoothstep(e + @suavidad, e - @suavidad, d);
float brillo = 1.0 - abs(m * 2.0 - 1.0);
@out = mix(@A, @B, m);
@out.rgb += @borde * brillo * 0.6;
